 input:=jsonb_build_object('targetSlug','es-ct-segona-g1','competitionId',783,'sourceCode','4109388-4109627','season','2026/27','sourceFingerprintSha256',v#>>'{inventoryBinding,sourceFingerprintSha256}','writerCommit',v->>'sourceCommit','fixtures',(select jsonb_agg(f order by id)from pg_temp._fcf_expected),'mapping',(select jsonb_agg(m order by m->>'sourceMatchId')from jsonb_array_elements(mp->'fixtures')m),'native',native);
 proposal:=jsonb_build_object('schemaVersion',1,'kind','fcf-future-launch-proposal','targetSlug','es-ct-segona-g1','competitionId',783,'season','2026/27','sourceCode','4109388-4109627','sourceFingerprintSha256',v#>>'{inventoryBinding,sourceFingerprintSha256}','writerCommit',v->>'sourceCommit','projectionSha256',pg_temp.g1_sha(pg_temp.g1_canonical(input)),'roundNumber',selected,'roundId',rid,'firstFantasyPlayedOn',opening,'timeZone','Europe/Madrid','earliestKickoffUTC',to_char(earliest at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'deadlineUTC',to_char(deadline at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'fixtureIds',(select jsonb_agg(id order by id)from pg_temp._fcf_expected where rn=selected),'matchIds',(select jsonb_agg(mid order by mid)from pg_temp._fcf_expected where rn=selected));
